import type { Frontmatter, Post, SiteConfig } from './types.js';
import { parse as parseMarkdown } from './parser.js';

export type { Frontmatter, Post, SiteConfig };

export interface Frontmatter {
  title: string;
  date: string;
  tags: string[];
  draft: boolean;
  layout: string;
}

export interface Post {
  slug: string;
  frontmatter: Frontmatter;
  raw: string;
  html: string;
  body: string;
}

export interface SiteConfig {
  src: string;
  templates: string;
  output: string;
  baseUrl: string;
  siteTitle: string;
  siteDescription: string;
}

export interface TemplateContext {
  title: string;
  posts: Post[];
  tags: Array<{ tag: string; posts: Post[] }>;
  site: { title: string; description: string; baseUrl: string };
  body?: string;
  page?: Post;
}

import fs from 'node:fs';
import path from 'node:path';
import matter from 'gray-matter';
import { marked } from 'marked';
import hljs from 'highlight.js';
import type { Frontmatter, Post } from './types.js';

const codeRenderer = {
  code(this: { text: string; lang?: string }): string {
    const lang = this.lang || '';
    const language = hljs.getLanguage(lang) ? lang : 'plaintext';
    const highlighted = hljs.highlight(this.text || '', { language }).value;
    return `<pre><code class="hljs language-${language}">${highlighted}</code></pre>`;
  },
};

marked.use({ renderer: codeRenderer });

export interface ParseResult {
  frontmatter: Frontmatter;
  raw: string;
  html: string;
}

const DEFAULT_FRONTMATTER: Frontmatter = {
  title: 'Untitled',
  date: new Date().toISOString().split('T')[0],
  tags: [],
  draft: false,
  layout: 'default',
};

export function parse(filePath: string): ParseResult {
  const raw = fs.readFileSync(filePath, 'utf-8');
  const { data, content } = matter(raw);

  const frontmatter: Frontmatter = {
    ...DEFAULT_FRONTMATTER,
    ...data,
    tags: Array.isArray(data.tags) ? data.tags : typeof data.tags === 'string' ? data.tags.split(',').map((t: string) => t.trim()) : [],
    draft: Boolean(data.draft),
  };

  const html = marked.parse(content) as string;

  return { frontmatter, raw: content, html };
}

export function parseAll(srcDir: string): Post[] {
  const files = collectMarkdownFiles(srcDir);

  return files
    .map((filePath) => {
      const relative = path.relative(srcDir, filePath);
      const slug = relative.replace(/\.md$/, '').replace(/\\/g, '/');
      const parsed = parse(filePath);
      return { slug, ...parsed, body: '' };
    })
    .sort((a, b) => new Date(b.frontmatter.date).getTime() - new Date(a.frontmatter.date).getTime());
}

function collectMarkdownFiles(dir: string): string[] {
  const results: string[] = [];
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...collectMarkdownFiles(full));
    } else if (entry.isFile() && entry.name.endsWith('.md')) {
      results.push(full);
    }
  }

  return results;
}

import fs from 'node:fs';
import path from 'node:path';
import Handlebars from 'handlebars';
import type { Post, SiteConfig, TemplateContext } from './types.js';

export interface Templates {
  layouts: Record<string, Handlebars.TemplateDelegate>;
  pages: Record<string, Handlebars.TemplateDelegate>;
}

export function loadTemplates(templateDir: string): Templates {
  const layouts: Record<string, Handlebars.TemplateDelegate> = {};
  const pages: Record<string, Handlebars.TemplateDelegate> = {};

  const partialsDir = path.join(templateDir, 'partials');
  if (fs.existsSync(partialsDir)) {
    for (const file of fs.readdirSync(partialsDir)) {
      if (file.endsWith('.hbs') || file.endsWith('.handlebars')) {
        const name = path.basename(file, path.extname(file));
        const source = fs.readFileSync(path.join(partialsDir, file), 'utf-8');
        Handlebars.registerPartial(name, source);
      }
    }
  }

  const layoutsDir = path.join(templateDir, 'layouts');
  if (fs.existsSync(layoutsDir)) {
    for (const file of fs.readdirSync(layoutsDir)) {
      if (file.endsWith('.hbs') || file.endsWith('.handlebars')) {
        const name = path.basename(file, path.extname(file));
        const source = fs.readFileSync(path.join(layoutsDir, file), 'utf-8');
        layouts[name] = Handlebars.compile(source);
      }
    }
  }

  const pagesDir = templateDir;
  for (const file of fs.readdirSync(pagesDir)) {
    if (
      (file.endsWith('.hbs') || file.endsWith('.handlebars')) &&
      file !== 'layouts' &&
      file !== 'partials'
    ) {
      const name = path.basename(file, path.extname(file));
      const filePath = path.join(pagesDir, file);
      const source = fs.readFileSync(filePath, 'utf-8');
      pages[name] = Handlebars.compile(source);
    }
    if (
      fs.statSync(path.join(pagesDir, file)).isFile() &&
      (file.endsWith('.hbs') || file.endsWith('.handlebars'))
    ) {
      const name = path.basename(file, path.extname(file));
      const source = fs.readFileSync(path.join(pagesDir, file), 'utf-8');
      pages[name] = Handlebars.compile(source);
    }
  }

  return { layouts, pages };
}

export function renderPage(
  templates: Templates,
  templateName: string,
  context: TemplateContext,
): string {
  const pageTemplate = templates.pages[templateName];
  if (!pageTemplate) {
    throw new Error(`Template "${templateName}" not found. Available: ${Object.keys(templates.pages).join(', ')}`);
  }

  const innerHtml = pageTemplate(context);

  const layoutName = context.page?.frontmatter?.layout || 'default';
  const layout = templates.layouts[layoutName];
  if (layout) {
    return layout({ ...context, body: innerHtml, content: innerHtml });
  }

  return innerHtml;
}

Handlebars.registerHelper('dateFormat', function (dateStr: string) {
  if (!dateStr) return '';
  const d = new Date(dateStr);
  return d.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
});

Handlebars.registerHelper('eq', function (a: unknown, b: unknown) {
  return a === b;
});

Handlebars.registerHelper('encodeURI', function (str: string) {
  return encodeURIComponent(str);
});

import RSS from 'rss';
import type { Post, SiteConfig } from './types.js';

export function generateRSS(posts: Post[], config: SiteConfig): string {
  const published = posts.filter((p) => !p.frontmatter.draft);

  const feed = new RSS({
    title: config.siteTitle,
    description: config.siteDescription,
    feed_url: `${config.baseUrl}/rss.xml`,
    site_url: config.baseUrl,
    language: 'en',
    pubDate: published.length > 0 ? published[0].frontmatter.date : new Date().toISOString(),
  });

  for (const post of published) {
    feed.item({
      title: post.frontmatter.title,
      description: post.html.slice(0, 500),
      url: `${config.baseUrl}/${post.slug}.html`,
      date: post.frontmatter.date,
      categories: post.frontmatter.tags,
    });
  }

  return feed.xml({ indent: true });
}

import fs from 'node:fs';
import path from 'node:path';
import { parseAll } from './parser.js';
import { loadTemplates, renderPage } from './renderer.js';
import { generateRSS } from './rss.js';
import type { Post, SiteConfig, TemplateContext } from './types.js';

const RELOAD_SCRIPT = `
<script>
  (function() {
    var ws = new WebSocket('ws://' + location.host + '/__reload');
    ws.onmessage = function(msg) {
      if (msg.data === 'reload') location.reload();
    };
  })();
</script>`;

export function generate(config: SiteConfig, injectReload: boolean = false): void {
  fs.mkdirSync(config.output, { recursive: true });

  const posts = parseAll(config.src);
  const published = posts.filter((p) => !p.frontmatter.draft);
  const templates = loadTemplates(config.templates);

  for (const post of published) {
    const ctx: TemplateContext = {
      title: post.frontmatter.title,
      posts: published,
      tags: buildTagIndex(published),
      site: { title: config.siteTitle, description: config.siteDescription, baseUrl: config.baseUrl },
      page: post,
    };

    let html = renderPage(templates, 'post', ctx);
    if (injectReload) html += RELOAD_SCRIPT;

    const outPath = path.join(config.output, `${post.slug}.html`);
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, html);
  }

  const indexCtx: TemplateContext = {
    title: config.siteTitle,
    posts: published,
    tags: buildTagIndex(published),
    site: { title: config.siteTitle, description: config.siteDescription, baseUrl: config.baseUrl },
  };

  let indexHtml = renderPage(templates, 'index', indexCtx);
  if (injectReload) indexHtml += RELOAD_SCRIPT;
  fs.writeFileSync(path.join(config.output, 'index.html'), indexHtml);

  const tagIndex = buildTagIndex(published);
  for (const { tag, posts: tagPosts } of tagIndex) {
    const tagCtx: TemplateContext = {
      title: `Posts tagged "${tag}"`,
      posts: tagPosts,
      tags: tagIndex,
      site: { title: config.siteTitle, description: config.siteDescription, baseUrl: config.baseUrl },
    };

    let tagHtml = renderPage(templates, 'tag', tagCtx);
    if (injectReload) tagHtml += RELOAD_SCRIPT;

    const tagDir = path.join(config.output, 'tags', encodeURIComponent(tag));
    fs.mkdirSync(tagDir, { recursive: true });
    fs.writeFileSync(path.join(tagDir, 'index.html'), tagHtml);
  }

  const rssXml = generateRSS(published, config);
  fs.writeFileSync(path.join(config.output, 'rss.xml'), rssXml);

  if (templates.layouts['default'] && !injectReload) {
    copyAssets(config.templates, config.output);
  }
}

function buildTagIndex(posts: Post[]): Array<{ tag: string; posts: Post[] }> {
  const map = new Map<string, Post[]>();
  for (const post of posts) {
    if (post.frontmatter.draft) continue;
    for (const tag of post.frontmatter.tags) {
      if (!map.has(tag)) map.set(tag, []);
      map.get(tag)!.push(post);
    }
  }
  return [...map.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([tag, posts]) => ({ tag, posts }));
}

function copyAssets(srcDir: string, outDir: string): void {
  const exclude = new Set(['.hbs', '.handlebars']);
  function walk(dir: string) {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      const relative = path.relative(srcDir, full);
      const dest = path.join(outDir, relative);
      if (entry.isDirectory() && entry.name !== 'layouts' && entry.name !== 'partials') {
        fs.mkdirSync(dest, { recursive: true });
        walk(full);
      } else if (entry.isFile() && !exclude.has(path.extname(entry.name))) {
        fs.mkdirSync(path.dirname(dest), { recursive: true });
        fs.copyFileSync(full, dest);
      }
    }
  }
  walk(srcDir);
}

import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { WebSocketServer } from 'ws';
import chokidar from 'chokidar';
import type { SiteConfig } from './types.js';
import { generate } from './generator.js';

const RELOAD_SCRIPT = `
<script>
  (function() {
    var ws = new WebSocket('ws://' + location.host + '/__reload');
    ws.onmessage = function(msg) {
      if (msg.data === 'reload') location.reload();
    };
    ws.onclose = function() {
      setTimeout(function() {
        (function() {
          var ws = new WebSocket('ws://' + location.host + '/__reload');
          ws.onmessage = function(msg) {
            if (msg.data === 'reload') location.reload();
          };
        })();
      }, 1000);
    };
  })();
</script>`;

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.xml': 'application/xml; charset=utf-8',
  '.ico': 'image/x-icon',
};

export function startDevServer(config: SiteConfig, port: number = 8080): void {
  generate(config, true);

  const server = http.createServer((req, res) => {
    if (!req.url) {
      res.writeHead(400);
      res.end();
      return;
    }

    const urlPath = req.url.split('?')[0];
    const filePath = urlPath === '/' || urlPath === ''
      ? path.join(config.output, 'index.html')
      : path.join(config.output, urlPath);

    const ext = path.extname(filePath).toLowerCase();

    try {
      const content = fs.readFileSync(filePath);
      res.writeHead(200, { 'Content-Type': MIME_TYPES[ext] || 'application/octet-stream' });
      res.end(content);
    } catch {
      if (ext === '.html' || ext === '') {
        try {
          const htmlPath = filePath.endsWith('.html') ? filePath : filePath + '.html';
          const content = fs.readFileSync(htmlPath);
          res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
          res.end(content);
        } catch {
          res.writeHead(404, { 'Content-Type': 'text/html; charset=utf-8' });
          res.end('<h1>404 - Not Found</h1>');
        }
      } else {
        res.writeHead(404);
        res.end();
      }
    }
  });

  const wss = new WebSocketServer({ server, path: '/__reload' });

  wss.on('connection', (ws) => {
    ws.on('error', () => {});
  });

  const watcher = chokidar.watch([
    path.join(config.src, '**/*.md'),
    path.join(config.templates, '**/*.{hbs,handlebars}'),
  ], {
    ignoreInitial: true,
    awaitWriteFinish: { stabilityThreshold: 100, pollInterval: 50 },
  });

  function rebroadcast() {
    for (const client of wss.clients) {
      if (client.readyState === 1) {
        client.send('reload');
      }
    }
  }

  watcher.on('change', () => {
    generate(config, true);
    rebroadcast();
  });

  watcher.on('add', () => {
    generate(config, true);
    rebroadcast();
  });

  watcher.on('unlink', () => {
    generate(config, true);
    rebroadcast();
  });

  server.listen(port, () => {
    console.log(`Dev server running at http://localhost:${port}`);
    console.log(`Watching for changes in ${config.src} and ${config.templates}`);
  });
}

#!/usr/bin/env node
import yargs from 'yargs';
import { hideBin } from 'yargs/helpers';
import { generate } from './generator.js';
import { startDevServer } from './server.js';
import type { SiteConfig } from './types.js';

yargs(hideBin(process.argv))
  .scriptName('ssg')
  .command(
    'build',
    'Generate static HTML site',
    (y) =>
      y
        .option('src', { type: 'string', default: 'content', describe: 'Source directory of Markdown files' })
        .option('templates', { type: 'string', default: 'templates', describe: 'Template directory' })
        .option('output', { type: 'string', default: 'public', describe: 'Output directory' })
        .option('base-url', { type: 'string', default: 'http://localhost:8080', describe: 'Base URL for RSS and links' })
        .option('site-title', { type: 'string', default: 'My Site', describe: 'Site title' })
        .option('site-description', { type: 'string', default: 'A static site', describe: 'Site description' }),
    async (argv) => {
      const config: SiteConfig = {
        src: argv.src,
        templates: argv.templates,
        output: argv.output,
        baseUrl: argv['base-url'],
        siteTitle: argv['site-title'],
        siteDescription: argv['site-description'],
      };
      generate(config);
      console.log(`Site built to ${config.output}`);
    },
  )
  .command(
    'serve',
    'Start dev server with live reload',
    (y) =>
      y
        .option('src', { type: 'string', default: 'content', describe: 'Source directory of Markdown files' })
        .option('templates', { type: 'string', default: 'templates', describe: 'Template directory' })
        .option('output', { type: 'string', default: 'public', describe: 'Output directory' })
        .option('base-url', { type: 'string', default: 'http://localhost:8080', describe: 'Base URL' })
        .option('site-title', { type: 'string', default: 'My Site', describe: 'Site title' })
        .option('site-description', { type: 'string', default: 'A static site', describe: 'Site description' })
        .option('port', { type: 'number', default: 8080, describe: 'Dev server port' }),
    async (argv) => {
      const config: SiteConfig = {
        src: argv.src,
        templates: argv.templates,
        output: argv.output,
        baseUrl: argv['base-url'],
        siteTitle: argv['site-title'],
        siteDescription: argv['site-description'],
      };
      startDevServer(config, argv.port);
    },
  )
  .demandCommand(1, 'You need at least one command before moving on')
  .strict()
  .help()
  .parse();

