import { describe, it, expect } from 'vitest';
import { parse } from '../src/parser.js';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const fixtures = path.join(__dirname, 'fixtures', 'posts');

describe('parse', () => {
  it('parses frontmatter title', () => {
    const result = parse(path.join(fixtures, 'post1.md'));
    expect(result.frontmatter.title).toBe('Hello World');
  });

  it('parses frontmatter date', () => {
    const result = parse(path.join(fixtures, 'post1.md'));
    expect(result.frontmatter.date).toBe('2024-01-15');
  });

  it('parses frontmatter tags', () => {
    const result = parse(path.join(fixtures, 'post1.md'));
    expect(result.frontmatter.tags).toEqual(['javascript', 'tutorial']);
  });

  it('parses draft flag as false by default', () => {
    const result = parse(path.join(fixtures, 'post1.md'));
    expect(result.frontmatter.draft).toBe(false);
  });

  it('parses draft flag as true', () => {
    const result = parse(path.join(fixtures, 'post2.md'));
    expect(result.frontmatter.draft).toBe(true);
  });

  it('converts markdown to HTML', () => {
    const result = parse(path.join(fixtures, 'post1.md'));
    expect(result.html).toContain('<h2>Getting Started</h2>');
  });

  it('applies syntax highlighting to code blocks', () => {
    const result = parse(path.join(fixtures, 'post1.md'));
    expect(result.html).toContain('class="hljs');
    expect(result.html).toContain('language-javascript');
  });

  it('uses plaintext for unknown languages', () => {
    const result = parse(path.join(fixtures, 'post3.md'));
    expect(result.html).toContain('language-plaintext');
  });

  it('handles missing frontmatter with defaults', () => {
    const result = parse(path.join(fixtures, 'post1.md'));
    expect(result.frontmatter.layout).toBe('default');
  });

  it('handles string tags converted to array', () => {
    const result = parse(path.join(fixtures, 'post3.md'));
    expect(result.frontmatter.tags).toEqual(['typescript', 'javascript']);
  });

  it('handles posts with no tags', () => {
    const result = parse(path.join(fixtures, 'post2.md'));
    expect(result.frontmatter.tags).toEqual(['typescript']);
  });

  it('generates raw markdown content', () => {
    const result = parse(path.join(fixtures, 'post1.md'));
    expect(result.raw).toContain('## Getting Started');
    expect(result.raw).not.toContain('---');
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { loadTemplates, renderPage } from '../src/renderer.js';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import type { TemplateContext, Post, Frontmatter } from '../src/types.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const templatesDir = path.join(__dirname, 'fixtures', 'templates');

function makePost(overrides: Partial<Frontmatter> & { slug?: string; html?: string } = {}): Post {
  return {
    slug: overrides.slug || 'test-post',
    frontmatter: {
      title: overrides.title || 'Test Post',
      date: overrides.date || '2024-01-01',
      tags: overrides.tags || [],
      draft: overrides.draft ?? false,
      layout: overrides.layout || 'default',
    },
    raw: '',
    html: overrides.html || '<p>Test content</p>',
    body: '',
  };
}

const siteContext = {
  title: 'Test Site',
  posts: [],
  tags: [],
  site: { title: 'Test Site', description: 'A test site', baseUrl: 'http://localhost:8080' },
};

describe('renderer', () => {
  let templates: ReturnType<typeof loadTemplates>;

  beforeEach(() => {
    templates = loadTemplates(templatesDir);
  });

  it('loads page templates', () => {
    expect(Object.keys(templates.pages)).toContain('index');
    expect(Object.keys(templates.pages)).toContain('post');
    expect(Object.keys(templates.pages)).toContain('tag');
  });

  it('loads layout templates', () => {
    expect(Object.keys(templates.layouts)).toContain('default');
  });

  it('loads partials', () => {
    const postTemplate = templates.pages['post'];
    const post = makePost({ title: 'My Post' });
    const ctx: TemplateContext = { ...siteContext, posts: [post], page: post };
    const html = renderPage(templates, 'post', ctx);
    expect(html).toContain('My Post');
  });

  it('renders post with layout', () => {
    const post = makePost({ title: 'Layout Test' });
    const ctx: TemplateContext = { ...siteContext, posts: [post], page: post };
    const html = renderPage(templates, 'post', ctx);
    expect(html).toContain('<!DOCTYPE html>');
    expect(html).toContain('Layout Test');
    expect(html).toContain('<article>');
  });

  it('renders index page', () => {
    const posts = [
      makePost({ title: 'Post 1', slug: 'post-1' }),
      makePost({ title: 'Post 2', slug: 'post-2' }),
    ];
    const ctx: TemplateContext = { ...siteContext, posts };
    const html = renderPage(templates, 'index', ctx);
    expect(html).toContain('Post 1');
    expect(html).toContain('Post 2');
    expect(html).toContain('post-1.html');
  });

  it('renders tag page', () => {
    const posts = [makePost({ title: 'Tagged Post', slug: 'tagged' })];
    const ctx: TemplateContext = { ...siteContext, posts, title: 'Posts tagged "js"' };
    const html = renderPage(templates, 'tag', ctx);
    expect(html).toContain('Tagged Post');
    expect(html).toContain('tagged.html');
  });

  it('includes partials in rendered output', () => {
    const post = makePost();
    const ctx: TemplateContext = { ...siteContext, posts: [post], page: post };
    const html = renderPage(templates, 'post', ctx);
    expect(html).toContain('Home');
    expect(html).toContain('<nav>');
  });

  it('renders date with dateFormat helper', () => {
    const post = makePost({ date: '2024-01-15' });
    const ctx: TemplateContext = { ...siteContext, posts: [post], page: post };
    const html = renderPage(templates, 'post', ctx);
    expect(html).toContain('January 15, 2024');
  });

  it('renders tags list when present', () => {
    const post = makePost({ tags: ['javascript', 'typescript'] });
    const ctx: TemplateContext = { ...siteContext, posts: [post], page: post };
    const html = renderPage(templates, 'post', ctx);
    expect(html).toContain('href="http://localhost:8080/tags/javascript/"');
    expect(html).toContain('href="http://localhost:8080/tags/typescript/"');
  });

  it('omits tags list when no tags', () => {
    const post = makePost({ tags: [] });
    const ctx: TemplateContext = { ...siteContext, posts: [post], page: post };
    const html = renderPage(templates, 'post', ctx);
    expect(html).not.toContain('<ul class="tags">');
  });

  it('renders post HTML content inside layout', () => {
    const post = makePost({ html: '<p><strong>Bold</strong> content</p>' });
    const ctx: TemplateContext = { ...siteContext, posts: [post], page: post };
    const html = renderPage(templates, 'post', ctx);
    expect(html).toContain('<strong>Bold</strong>');
  });

  it('throws for missing template', () => {
    expect(() => {
      const post = makePost();
      renderPage(templates, 'nonexistent', { ...siteContext, page: post });
    }).toThrow('Template "nonexistent" not found');
  });
});

import { describe, it, expect } from 'vitest';
import { generateRSS } from '../src/rss.js';
import type { Post, Frontmatter, SiteConfig } from '../src/types.js';

function makePost(overrides: Partial<Frontmatter> & { slug?: string; html?: string } = {}): Post {
  return {
    slug: overrides.slug || 'test-post',
    frontmatter: {
      title: overrides.title || 'Test',
      date: overrides.date || '2024-01-01',
      tags: overrides.tags || [],
      draft: overrides.draft ?? false,
      layout: overrides.layout || 'default',
    },
    raw: '',
    html: overrides.html || '<p>test</p>',
    body: '',
  };
}

const config: SiteConfig = {
  src: 'content',
  templates: 'templates',
  output: 'public',
  baseUrl: 'https://example.com',
  siteTitle: 'My Blog',
  siteDescription: 'A blog about things',
};

describe('RSS', () => {
  it('generates valid RSS XML', () => {
    const posts = [makePost({ title: 'Hello' })];
    const xml = generateRSS(posts, config);
    expect(xml).toContain('<?xml version="1.0"');
    expect(xml).toContain('<rss');
    expect(xml).toContain('<channel>');
    expect(xml).toContain('<title>My Blog</title>');
  });

  it('includes post items', () => {
    const posts = [makePost({ title: 'My Post', slug: 'my-post' })];
    const xml = generateRSS(posts, config);
    expect(xml).toContain('<title>My Post</title>');
    expect(xml).toContain('<link>https://example.com/my-post.html</link>');
  });

  it('excludes draft posts', () => {
    const posts = [
      makePost({ title: 'Published', draft: false }),
      makePost({ title: 'Draft', draft: true }),
    ];
    const xml = generateRSS(posts, config);
    expect(xml).toContain('Published');
    expect(xml).not.toContain('Draft');
  });

  it('includes tags as categories', () => {
    const posts = [makePost({ title: 'Tagged', tags: ['js', 'ts'] })];
    const xml = generateRSS(posts, config);
    expect(xml).toContain('<category>js</category>');
    expect(xml).toContain('<category>ts</category>');
  });

  it('includes site description', () => {
    const posts = [makePost()];
    const xml = generateRSS(posts, config);
    expect(xml).toContain('<description>A blog about things</description>');
  });

  it('includes feed URL', () => {
    const posts = [makePost()];
    const xml = generateRSS(posts, config);
    expect(xml).toContain('https://example.com/rss.xml');
  });

  it('handles empty post list', () => {
    const xml = generateRSS([], config);
    expect(xml).toContain('<rss');
    expect(xml).toContain('<channel>');
    expect(xml).toContain('<item>'); // pubDate item
  });

  it('sorts posts by date for pubDate', () => {
    const posts = [
      makePost({ title: 'Newer', date: '2024-06-01' }),
      makePost({ title: 'Older', date: '2024-01-01' }),
      makePost({ title: 'Middle', date: '2024-03-01' }),
    ];
    const xml = generateRSS(posts, config);
    expect(xml).toContain('Newer');
    expect(xml).toContain('Older');
  });
});

import { describe, it, expect, afterEach } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { execSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const fixtures = path.join(__dirname, 'fixtures');
const testOutput = path.join(__dirname, '..', 'test-output');
const projectRoot = path.join(__dirname, '..');
const cliPath = path.join(projectRoot, 'dist', 'cli.js');

function cleanOutput() {
  if (fs.existsSync(testOutput)) {
    fs.rmSync(testOutput, { recursive: true, force: true });
  }
}

afterEach(cleanOutput);

describe('CLI build command', () => {
  it('generates index.html', () => {
    execSync(
      `node ${cliPath} build --src ${path.join(fixtures, 'posts')} --templates ${path.join(fixtures, 'templates')} --output ${testOutput} --base-url http://localhost:8080 --site-title "Test Blog"`,
      { cwd: projectRoot, stdio: 'pipe' },
    );
    expect(fs.existsSync(path.join(testOutput, 'index.html'))).toBe(true);
  });

  it('generates post pages', () => {
    execSync(
      `node ${cliPath} build --src ${path.join(fixtures, 'posts')} --templates ${path.join(fixtures, 'templates')} --output ${testOutput} --base-url http://localhost:8080 --site-title "Test Blog"`,
      { cwd: projectRoot, stdio: 'pipe' },
    );
    expect(fs.existsSync(path.join(testOutput, 'post1.html'))).toBe(true);
    expect(fs.existsSync(path.join(testOutput, 'post3.html'))).toBe(true);
  });

  it('excludes draft posts from output', () => {
    execSync(
      `node ${cliPath} build --src ${path.join(fixtures, 'posts')} --templates ${path.join(fixtures, 'templates')} --output ${testOutput} --base-url http://localhost:8080 --site-title "Test Blog"`,
      { cwd: projectRoot, stdio: 'pipe' },
    );
    expect(fs.existsSync(path.join(testOutput, 'post2.html'))).toBe(false);
  });

  it('generates tag index pages', () => {
    execSync(
      `node ${cliPath} build --src ${path.join(fixtures, 'posts')} --templates ${path.join(fixtures, 'templates')} --output ${testOutput} --base-url http://localhost:8080 --site-title "Test Blog"`,
      { cwd: projectRoot, stdio: 'pipe' },
    );
    expect(fs.existsSync(path.join(testOutput, 'tags', 'javascript', 'index.html'))).toBe(true);
    expect(fs.existsSync(path.join(testOutput, 'tags', 'typescript', 'index.html'))).toBe(true);
    expect(fs.existsSync(path.join(testOutput, 'tags', 'tutorial', 'index.html'))).toBe(true);
  });

  it('generates RSS feed', () => {
    execSync(
      `node ${cliPath} build --src ${path.join(fixtures, 'posts')} --templates ${path.join(fixtures, 'templates')} --output ${testOutput} --base-url http://localhost:8080 --site-title "Test Blog"`,
      { cwd: projectRoot, stdio: 'pipe' },
    );
    expect(fs.existsSync(path.join(testOutput, 'rss.xml'))).toBe(true);
    const rss = fs.readFileSync(path.join(testOutput, 'rss.xml'), 'utf-8');
    expect(rss).toContain('Hello World');
    expect(rss).not.toContain('Second Post'); // draft excluded
  });

  it('accepts custom base-url flag', () => {
    execSync(
      `node ${cliPath} build --src ${path.join(fixtures, 'posts')} --templates ${path.join(fixtures, 'templates')} --output ${testOutput} --base-url https://mysite.com --site-title "Test Blog"`,
      { cwd: projectRoot, stdio: 'pipe' },
    );
    const index = fs.readFileSync(path.join(testOutput, 'index.html'), 'utf-8');
    expect(index).toContain('https://mysite.com');
    const rss = fs.readFileSync(path.join(testOutput, 'rss.xml'), 'utf-8');
    expect(rss).toContain('https://mysite.com');
  });

  it('accepts --site-title flag', () => {
    execSync(
      `node ${cliPath} build --src ${path.join(fixtures, 'posts')} --templates ${path.join(fixtures, 'templates')} --output ${testOutput} --base-url http://localhost:8080 --site-title "My Custom Site"`,
      { cwd: projectRoot, stdio: 'pipe' },
    );
    const index = fs.readFileSync(path.join(testOutput, 'index.html'), 'utf-8');
    expect(index).toContain('My Custom Site');
  });

  it('accepts --site-description flag', () => {
    execSync(
      `node ${cliPath} build --src ${path.join(fixtures, 'posts')} --templates ${path.join(fixtures, 'templates')} --output ${testOutput} --base-url http://localhost:8080 --site-title "Test" --site-description "Custom description"`,
      { cwd: projectRoot, stdio: 'pipe' },
    );
    const rss = fs.readFileSync(path.join(testOutput, 'rss.xml'), 'utf-8');
    expect(rss).toContain('Custom description');
  });

  it('uses default values when flags omitted', () => {
    execSync(
      `node ${cliPath} build --src ${path.join(fixtures, 'posts')} --templates ${path.join(fixtures, 'templates')} --output ${testOutput}`,
      { cwd: projectRoot, stdio: 'pipe' },
    );
    expect(fs.existsSync(path.join(testOutput, 'index.html'))).toBe(true);
  });

  it('includes syntax-highlighted code blocks in output', () => {
    execSync(
      `node ${cliPath} build --src ${path.join(fixtures, 'posts')} --templates ${path.join(fixtures, 'templates')} --output ${testOutput} --base-url http://localhost:8080 --site-title "Test Blog"`,
      { cwd: projectRoot, stdio: 'pipe' },
    );
    const post1 = fs.readFileSync(path.join(testOutput, 'post1.html'), 'utf-8');
    expect(post1).toContain('class="hljs');
    expect(post1).toContain('language-javascript');
  });
});

describe('CLI serve command', () => {
  it('supports --port flag in help', () => {
    const result = execSync(`node ${cliPath} serve --help`, { cwd: projectRoot, stdio: 'pipe' });
